head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.getDtsAccntPttn();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P10.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Acnt_OnLoadError
 * @description dts_Acnt 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Acnt_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Acnt);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P10.dts_Acnt_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Acnt_OnLoadCompleted
 * @description dts_Acnt 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Acnt_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_Acnt.errorMsg) {
            await $c.win.alert(dts_Acnt.errorMsg);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P10.dts_Acnt_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        // 닫기버튼 클릭
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P10.img_Close_onclick" });
    }
};

