/**
 * @method
 * @name trv_Acnt_OnContextMenu
 * @description trv Acnt On Context Menu 처리
 * @param {*} x x
 * @param {*} y y
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.trv_Acnt_OnContextMenu = function(x, y, row) {
    try {
        trv_Acnt.TrackPopupMenu(x, y);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00600_P10.trv_Acnt_OnContextMenu" });
    }
};

/**
 * @method
 * @name trv_Acnt_OnCommand
 * @description trv Acnt On Command 처리
 * @param {*} code code
 * @param {*} text text
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trv_Acnt_OnCommand = async function(code, text) {
    try {
        const nRow = dts_Acnt.getRowPosition();
        const ACCNT_CD = dts_Acnt.getCellData(nRow, "ACCNT_CD");
        const ACNTG_BAS_TYP = dts_Acnt.getCellData(nRow, "ACNTG_BAS_TYP");
        const IND_PTTN = dts_Acnt.getCellData(nRow, "IND_PTTN");
        const ACCNT_PTTN = dts_Acnt.getCellData(nRow, "ACCNT_PTTN");
        const INDVDL_CONN_TP = cmb_INDVDL_CONN_TP.getValue();
        const S_LV = dts_Acnt.getCellData(nRow, "LV");

        // alert( trv_SelectedAcnt.ItemText );
        // ACCNT_CD || '^' || TRIM(FSS_ACCNT_CD) || '^' || ID_VRF_ORD || '^'

        const array = trv_SelectedAcnt.ItemText.split("^");
        T_ACCNT_CD = array[0];
        T_FSS_ACCNT_LV = array[1];
        T_ORD = array[2];

        // 단건이동
        if (code === "1") {
            if (trv_SelectedAcnt.getSelectedNode().label === "") {
                await $c.win.alert("이동할 곳을 지정해 주세요");
                return;
            }
            // dts_ListUpdate.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            dts_ListUpdate.insertRow();
            dts_ListUpdate.setCellData(1, "S_ACCNT_CD", ACCNT_CD);
            dts_ListUpdate.setCellData(1, "S_TYP", ACNTG_BAS_TYP + IND_PTTN + ACCNT_PTTN + INDVDL_CONN_TP);
            dts_ListUpdate.setCellData(1, "S_LV", S_LV);
            dts_ListUpdate.setCellData(1, "T_ACCNT_CD", T_ACCNT_CD);
            dts_ListUpdate.setCellData(1, "T_ORD", /*ORG SRC: dts_ListUpdate.setNameValue(1, "T_ORD", dts_ListUpdate.NameValue(1, "T_ORD") = );*/ X = X);
            dts_ListUpdate.setCellData(1, "T_LV", T_FSS_ACCNT_LV);
            trs_save.KeyName = "toinb_dataid4";
            // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
            // const sbmParams = {
            //     EMP_NO : js_emp_no,
            //     EMP_NM : js_emp_nm
            // };
            const sbmOptions = {
                id : "sbm_trs_save",
                action : "/ConditionSrchAction.do",
                ref : "dts_ListUpdate",
                target : "trs_save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }

        // 하위포함이동
        if (code === "2") {
            if (trv_SelectedAcnt.getSelectedNode().label === "") {
                await $c.win.alert("이동할 곳을 지정해 주세요");
                return;
            }
            // dts_ListUpdate.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            dts_ListUpdate.insertRow();
            dts_ListUpdate.setCellData(1, "S_ACCNT_CD", ACCNT_CD);
            dts_ListUpdate.setCellData(1, "S_TYP", ACNTG_BAS_TYP + IND_PTTN + ACCNT_PTTN + INDVDL_CONN_TP);
            dts_ListUpdate.setCellData(1, "S_LV", S_LV);
            dts_ListUpdate.setCellData(1, "T_ACCNT_CD", T_ACCNT_CD);
            dts_ListUpdate.setCellData(1, "T_ORD", /*ORG SRC: dts_ListUpdate.setNameValue(1, "T_ORD", dts_ListUpdate.NameValue(1, "T_ORD") = );*/ X = X);
            dts_ListUpdate.setCellData(1, "T_LV", T_FSS_ACCNT_LV);
            trs_save.KeyName = "toinb_dataid4";
            // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
            // const sbmParams = {
            //     EMP_NO : js_emp_no,
            //     EMP_NM : js_emp_nm
            // };
            const sbmOptions = {
                id : "sbm_trs_save",
                action : "/ConditionSrchAction.do",
                ref : "dts_ListUpdate",
                target : "trs_save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }

        // LV 1증가
        if (code === "3") {
            const plus = "1";
            // dts_ListUpdate.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
            dts_ListUpdate.insertRow();
            dts_ListUpdate.setCellData(1, "S_ACCNT_CD", ACCNT_CD);
            dts_ListUpdate.setCellData(1, "S_TYP", ACNTG_BAS_TYP + IND_PTTN + ACCNT_PTTN + INDVDL_CONN_TP);
            dts_ListUpdate.setCellData(1, "S_LV", plus);
            trs_save.KeyName = "toinb_dataid4";
            // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
            // const sbmParams = {
            //     EMP_NO : js_emp_no,
            //     EMP_NM : js_emp_nm
            // };
            const sbmOptions = {
                id : "sbm_trs_save",
                action : "/ConditionSrchAction.do",
                ref : "dts_ListUpdate",
                target : "trs_save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }

        // LV 1감소
        if (code === "4") {
            const minus = "-1";
            // dts_ListUpdate.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
            dts_ListUpdate.insertRow();
            dts_ListUpdate.setCellData(1, "S_ACCNT_CD", ACCNT_CD);
            dts_ListUpdate.setCellData(1, "S_TYP", ACNTG_BAS_TYP + IND_PTTN + ACCNT_PTTN + INDVDL_CONN_TP);
            dts_ListUpdate.setCellData(1, "S_LV", minus);
            trs_save.KeyName = "toinb_dataid4";
            // [전환검토] trs_save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
            // const sbmParams = {
            //     EMP_NO : js_emp_no,
            //     EMP_NM : js_emp_nm
            // };
            const sbmOptions = {
                id : "sbm_trs_save",
                action : "/ConditionSrchAction.do",
                ref : "dts_ListUpdate",
                target : "trs_save=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P10.trv_Acnt_OnCommand" });
    }
};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P10.trs_save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_save_OnFail
 * @description save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnFail = async function() {
    try {
        await $c.win.alert('trs_save.OnFail()');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00600_P10.trs_save_OnFail" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getDtsAccntPttn
 * @description 재무유형 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDtsAccntPttn = async function() {
    dts_AccntPttn.removeAll();
    const sbmOptions = {
        id : "sbm_dts_AccntPttn",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_AccntPttn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    dts_Acnt.removeAll();
    dts_SelectAcnt.removeAll();
    const sbmOptions = {
        id : "sbm_dts_Acnt",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Acnt=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_SelectAcnt",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_SelectAcnt=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
